package com.collabboard.config;
import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Configuration;import org.springframework.web.servlet.config.annotation.*;
@Configuration public class CorsConfig implements WebMvcConfigurer {@Value("${app.cors.allowed-origin:http://localhost:5173}")private String frontendOrigin;@Override public void addCorsMappings(CorsRegistry registry){registry.addMapping("/api/**").allowedOrigins(frontendOrigin).allowCredentials(true).allowedMethods("GET","POST","PATCH","DELETE","OPTIONS").allowedHeaders("Content-Type","X-Requested-With").maxAge(3600);}}
